div.script:

const c = document.getElementById('c');
const ctx = c.getContext('2d');
let w, h;
const particles = [];
let windX = 0, windY = 0, windTime = 0, lastInteractionTime = 0;
let flameOffsetX = 0, flameOffsetY = 0, targetFlameX = 0, targetFlameY = 0;
let tiltX = 0, tiltY = 0;

function resize() {
    w = c.width = window.innerWidth;
    h = c.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

function applyWind(clientX, clientY) {
    const now = Date.now();
    if (now - lastInteractionTime > 1000) windTime = 15;
    lastInteractionTime = now;
    windX = (clientX - w/2) * 0.003;
    windY = (clientY - h/2) * 0.002;
    if (windTime > 0) {
        targetFlameX = (clientX - w/2) * 0.02;
        targetFlameY = (clientY - h/2) * 0.015;
    }
}

c.addEventListener('touchstart', (e) => {
    lastInteractionTime = Date.now();
    windTime = 15;
    applyWind(e.touches[0].clientX, e.touches[0].clientY);
    e.preventDefault();
}, {passive: false});
c.addEventListener('touchmove', (e) => {
    applyWind(e.touches[0].clientX, e.touches[0].clientY);
    e.preventDefault();
}, {passive: false});
c.addEventListener('touchend', (e) => {
    windTime = 0;
    e.preventDefault();
});
c.addEventListener('mousedown', (e) => {
    lastInteractionTime = Date.now();
    windTime = 15;
    applyWind(e.clientX, e.clientY);
});
c.addEventListener('mousemove', (e) => {
    if (e.buttons === 1) applyWind(e.clientX, e.clientY);
});
c.addEventListener('mouseup', () => { windTime = 0; });

if (window.DeviceOrientationEvent) {
    window.addEventListener('deviceorientation', (e) => {
        if (e.gamma === null || e.beta === null) return;
        let gamma = e.gamma, beta = e.beta, tolerance = 8, deadzone = 5, effectiveGamma = 0;
        if (Math.abs(beta) < deadzone && Math.abs(gamma) < deadzone) return;
        if (Math.abs(gamma) > tolerance) effectiveGamma = gamma > 0 ? gamma - tolerance : gamma + tolerance;
        let multiplier = (Math.abs(beta) <= 90) ? -1 : 1;
        let targetX = effectiveGamma * 0.1 * multiplier;
        tiltX += (targetX - tiltX) * 0.4;
        tiltY = beta * 0.1;
    });
}

class P {
    constructor() { this.reset(); }
    reset() {
        this.x = w / 2;
        this.y = h / 2 + 50;
        this.vx = (Math.random() - 0.5) * 2;
        this.vy = (Math.random() * -2) - 1;
        this.life = 1.0;
        this.decay = (Math.random() * 0.02) + 0.01;
        this.size = (Math.random() * 20) + 20;
    }
    update() {
        this.life -= this.decay;
        if (this.life <= 0) { this.reset(); return; }
        let t = Date.now() * 0.002;
        let noise = Math.sin(this.y * 0.01 + t) * Math.cos(this.x * 0.01 + t);
        this.x += this.vx + (noise * 0.5);
        this.y += this.vy;
        if (windTime > 0) {
            this.vx += windX * 0.15;
            this.vy += windY * 0.1;
        }
        this.vx += (w/2 - this.x) * 0.002;
        this.size *= 0.96;
    }
    draw() {
        ctx.beginPath();
        let g = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.size);
        let r = Math.floor(255 * this.life), gr = Math.floor(140 * this.life), b = Math.floor(50 * this.life * this.life);
        g.addColorStop(0, `rgba(255, 255, 255, ${this.life})`); 
        g.addColorStop(0.4, `rgba(255, 255, 200, ${this.life})`);
        g.addColorStop(0.7, `rgba(255, 150, 0, ${this.life})`);  
        g.addColorStop(1, `rgba(${r}, ${gr}, ${b}, 0)`); 
        ctx.fillStyle = g;
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
    }
}

for(let i=0; i<150; i++) particles.push(new P());

function getBaseInfo() {
    let t = Date.now() * 0.002;
    const by = h / 2 + 80 + Math.cos(t * 3) * 1;
    const bx = w / 2 + Math.sin(t * 2.5) * 1.5;
    const size = 30 + Math.sin(t * 1) * 2; 
    return { bx, by, size };
}

function drawBase(bx, by, size) {
    ctx.beginPath();
    let g = ctx.createLinearGradient(bx, by - size, bx, by + size);
    g.addColorStop(0, 'rgba(255, 255, 255, 1)');
    g.addColorStop(0.4, 'rgba(255, 200, 50, 0.8)');
    g.addColorStop(1, 'rgba(255, 100, 0, 0)');
    ctx.fillStyle = g;
    ctx.ellipse(bx, by, size, size * 1.8, 0, 0, Math.PI * 2);
    ctx.fill();
}

function drawWick(bx, by, baseSize) {
    ctx.beginPath();
    ctx.ellipse(bx, by + baseSize + 5, baseSize * 0.3, baseSize * 0.6, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#000000'; 
    ctx.fill();
}

function anim() {
    ctx.clearRect(0, 0, w, h);
    flameOffsetX += (targetFlameX - flameOffsetX) * 0.6;
    flameOffsetY += (targetFlameY - flameOffsetY) * 0.6;
    const baseInfo = getBaseInfo();
    ctx.save();
    const pivotX = baseInfo.bx, pivotY = baseInfo.by + 20;
    ctx.translate(pivotX, pivotY); 
    let skew = Math.max(-0.8, Math.min(0.8, -tiltX * 0.4)); 
    ctx.transform(1 + Math.abs(skew) * 0.2, 0, skew, 1 + Math.abs(skew) * 0.1, 0, 0); 
    ctx.translate(-pivotX, -pivotY);
    drawBase(baseInfo.bx, baseInfo.by, baseInfo.size);
    ctx.globalCompositeOperation = 'lighter';
    ctx.save();
    ctx.translate(flameOffsetX, flameOffsetY);
    for(let p of particles) { p.update(); p.draw(); }
    ctx.restore();
    ctx.globalCompositeOperation = 'source-over';
    drawWick(baseInfo.bx, baseInfo.by, baseInfo.size);
    ctx.restore();
    if (windTime > 0) windTime--;
    requestAnimationFrame(anim);
}
anim();
